432                     /* If using the CKN table, fetch the SAK at this CKN table index. */
>>>     CID 1644406:  Null pointer dereferences  (FORWARD_NULL)
>>>     Dereferencing null pointer "ckn_table".
433                     const mka_ckn_info_key_t *key = &ckn_table[table_index].key;
434     
435                     sak = key->saks[an];
436                     name = ckn_table[table_index].name;
